from AlgorithmImports import *
from collections import deque
from math import floor


class IndependentParallelStrategiesAlgorithm(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}

        for ticker in self.tickers:
            equity = self.AddEquity(ticker, Resolution.Daily)
            self.symbols[ticker] = equity.Symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD,
            MovingAverageType.Wilders
        )

        self.spy_pending_order_id = None
        self.aapl_pending_order_id = None

    def OnData(self, data):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_close = None
        spy_sma = None
        spy_crosses_above = False
        spy_crosses_below = False

        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_close)

            if len(self.spy_closes) == self.SMA_PERIOD:
                spy_sma = sum(self.spy_closes) / self.SMA_PERIOD

                if (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                ):
                    spy_crosses_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_close > spy_sma
                    )
                    spy_crosses_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_close < spy_sma
                    )

                self.previous_spy_close = spy_close
                self.previous_spy_sma = spy_sma

        aapl_close = None

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close
            self.aapl_rsi.Update(self.Time, aapl_close)

        if len(bars) != len(self.tickers):
            return

        self.ProcessStrategyA(
            spy_close,
            spy_sma,
            spy_crosses_above,
            spy_crosses_below
        )
        self.ProcessStrategyB(aapl_close)

    def ProcessStrategyA(
        self,
        close,
        sma,
        crosses_above,
        crosses_below
    ):
        symbol = self.symbols["SPY"]
        lot_quantity = int(self.Portfolio[symbol].Quantity)

        if lot_quantity > 0:
            if (
                self.spy_pending_order_id is None
                and crosses_below
            ):
                ticket = self.MarketOrder(symbol, -lot_quantity)
                self.spy_pending_order_id = ticket.OrderId
            return

        if self.spy_pending_order_id is not None:
            return

        if sma is None:
            return

        if crosses_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = floor(target_value / close)

            if quantity > 0:
                ticket = self.MarketOrder(symbol, quantity)
                self.spy_pending_order_id = ticket.OrderId

    def ProcessStrategyB(self, close):
        symbol = self.symbols["AAPL"]
        lot_quantity = int(self.Portfolio[symbol].Quantity)

        if lot_quantity > 0:
            if (
                self.aapl_pending_order_id is None
                and self.aapl_rsi.IsReady
                and float(self.aapl_rsi.Current.Value) > 60
            ):
                ticket = self.MarketOrder(symbol, -lot_quantity)
                self.aapl_pending_order_id = ticket.OrderId
            return

        if self.aapl_pending_order_id is not None:
            return

        if not self.aapl_rsi.IsReady:
            return

        if self.aapl_red_streak >= 3:
            cash_required = 20_000.0

            if float(self.Portfolio.Cash) >= cash_required:
                quantity = floor(cash_required / close)

                if quantity > 0:
                    ticket = self.MarketOrder(symbol, quantity)
                    self.aapl_pending_order_id = ticket.OrderId

    def OnOrderEvent(self, order_event):
        if order_event.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            return

        if order_event.OrderId == self.spy_pending_order_id:
            self.spy_pending_order_id = None

        if order_event.OrderId == self.aapl_pending_order_id:
            self.aapl_pending_order_id = None

