class IndependentStrategiesAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_sma_period = 20
        self.spy_closes = deque(maxlen=self.spy_sma_period + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.aapl_rsi = RelativeStrengthIndex(
            14,
            MovingAverageType.WILDERS
        )

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = data.bars

        for ticker in self.tickers:
            symbol = self.symbols[ticker]
            if symbol not in bars:
                continue

            bar = bars[symbol]

            if ticker == "SPY":
                self.spy_closes.append(float(bar.close))

            elif ticker == "AAPL":
                close = float(bar.close)

                if self.aapl_previous_close is None:
                    self.aapl_red_streak = 0
                elif close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                self.aapl_previous_close = close
                self.aapl_rsi.update(bar.end_time, close)

        if any(self.symbols[ticker] not in bars for ticker in self.tickers):
            return

        self.spy_lot = int(self.portfolio[self.symbols["SPY"]].quantity)
        self.aapl_lot = int(self.portfolio[self.symbols["AAPL"]].quantity)

        self._evaluate_strategy_a(bars[self.symbols["SPY"]])
        self._evaluate_strategy_b(bars[self.symbols["AAPL"]])

    def _evaluate_strategy_a(self, bar: TradeBar):
        if len(self.spy_closes) < self.spy_sma_period + 1:
            return

        yesterday_close = self.spy_closes[-2]
        today_close = self.spy_closes[-1]

        yesterday_sma = (
            sum(list(self.spy_closes)[:self.spy_sma_period])
            / self.spy_sma_period
        )
        today_sma = (
            sum(list(self.spy_closes)[1:])
            / self.spy_sma_period
        )

        crosses_above = (
            yesterday_close <= yesterday_sma
            and today_close > today_sma
        )
        crosses_below = (
            yesterday_close >= yesterday_sma
            and today_close < today_sma
        )

        symbol = self.symbols["SPY"]

        if self.spy_lot > 0:
            if crosses_below:
                self.market_order(symbol, -self.spy_lot)
                self.spy_lot = 0
            return

        if crosses_above:
            quantity = floor(
                0.40 * float(self.portfolio.total_portfolio_value)
                / float(bar.close)
            )
            if quantity > 0:
                self.market_order(symbol, quantity)
                self.spy_lot = quantity

    def _evaluate_strategy_b(self, bar: TradeBar):
        if not self.aapl_rsi.is_ready:
            return

        symbol = self.symbols["AAPL"]

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.current.value) > 60:
                self.market_order(symbol, -self.aapl_lot)
                self.aapl_lot = 0
            return

        if self.aapl_red_streak >= 3:
            cash_required = 20_000.0
            available_cash = float(self.portfolio.cash)

            if available_cash >= cash_required:
                quantity = floor(cash_required / float(bar.close))
                if quantity > 0:
                    self.market_order(symbol, quantity)
                    self.aapl_lot = quantity

