class ExactStrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_sma = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

        self.spy_pending_order = False
        self.aapl_pending_order = False
        self.order_strategies = {}

        self.SetWarmUp(21, Resolution.Daily)

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = data.Bars[spy] if data.Bars.ContainsKey(spy) else None
        aapl_bar = data.Bars[aapl] if data.Bars.ContainsKey(aapl) else None

        spy_previous_close = self.previous_spy_close
        spy_previous_sma = self.previous_spy_sma

        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(
            data.Bars.ContainsKey(symbol)
            for symbol in self.symbols.values()
        )

        if (
            all_bars_present
            and not self.IsWarmingUp
            and self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and spy_previous_close is not None
            and spy_previous_sma is not None
            and self.previous_aapl_close is not None
        ):
            spy_crossed_below = (
                spy_previous_close >= spy_previous_sma
                and spy_bar.Close < self.spy_sma.Current.Value
            )
            spy_crossed_above = (
                spy_previous_close <= spy_previous_sma
                and spy_bar.Close > self.spy_sma.Current.Value
            )

            if (
                self.spy_lot > 0
                and not self.spy_pending_order
                and spy_crossed_below
            ):
                self._submit_order(spy, -self.spy_lot, "SPY")
            elif (
                self.spy_lot == 0
                and not self.spy_pending_order
                and spy_crossed_above
            ):
                quantity = int(self.CalculateOrderQuantity(spy, 0.40))
                if quantity > 0:
                    self._submit_order(spy, quantity, "SPY")

            if (
                self.aapl_lot > 0
                and not self.aapl_pending_order
                and self.aapl_rsi.Current.Value > 60
            ):
                self._submit_order(aapl, -self.aapl_lot, "AAPL")
            elif (
                self.aapl_lot == 0
                and not self.aapl_pending_order
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = int(20_000 // aapl_bar.Close)
                if quantity > 0:
                    self._submit_order(aapl, quantity, "AAPL")

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def _submit_order(self, symbol, quantity, strategy):
        if strategy == "SPY":
            self.spy_pending_order = True
        else:
            self.aapl_pending_order = True

        ticket = self.MarketOrder(symbol, quantity, False, strategy)
        self.order_strategies[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.Status in [
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ]:
            if strategy == "SPY":
                self.spy_lot += order_event.FillQuantity
                self.spy_lot = max(0, self.spy_lot)
            else:
                self.aapl_lot += order_event.FillQuantity
                self.aapl_lot = max(0, self.aapl_lot)

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            if strategy == "SPY":
                self.spy_pending_order = False
            else:
                self.aapl_pending_order = False

            self.order_strategies.pop(order_event.OrderId, None)

