class IndependentParallelStrategiesAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in self.tickers
        }

        self.spy_closes = deque(maxlen=101)
        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_previous_close = None
        self.rsi_gain_seed = deque(maxlen=self.rsi_period)
        self.rsi_loss_seed = deque(maxlen=self.rsi_period)
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

        self.order_records = {}

    def OnData(self, data):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)

            if "AAPL" in self.previous_closes:
                previous_close = self.previous_closes["AAPL"]
                if aapl_close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.UpdateAaplRsi(aapl_close)

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = float(bar.Close)

        if len(bars) != len(self.tickers):
            return

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        spy_crosses_above = False
        spy_crosses_below = False

        if len(self.spy_closes) == 101:
            closes = list(self.spy_closes)
            yesterday_sma = sum(closes[0:100]) / 100.0
            today_sma = sum(closes[1:101]) / 100.0
            yesterday_close = closes[-2]

            spy_crosses_above = (
                yesterday_close <= yesterday_sma and spy_close > today_sma
            )
            spy_crosses_below = (
                yesterday_close >= yesterday_sma and spy_close < today_sma
            )

        # Evaluate all sells before any buys.
        if (
            self.strategy_a_quantity > 0
            and not self.strategy_a_pending
            and spy_crosses_below
        ):
            ticket = self.MarketOrder(
                self.symbols["SPY"], -self.strategy_a_quantity
            )
            self.strategy_a_pending = True
            self.order_records[ticket.OrderId] = ("A", "sell")

        if (
            self.strategy_b_quantity > 0
            and not self.strategy_b_pending
            and self.aapl_rsi is not None
            and self.aapl_rsi > 60.0
        ):
            ticket = self.MarketOrder(
                self.symbols["AAPL"], -self.strategy_b_quantity
            )
            self.strategy_b_pending = True
            self.order_records[ticket.OrderId] = ("B", "sell")

        if (
            self.strategy_a_quantity == 0
            and not self.strategy_a_pending
