from AlgorithmImports import *
from collections import deque
from decimal import Decimal
import math


class IndependentParallelStrategiesAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_current_sma = None
        self.spy_previous_sma = None
        self.spy_previous_close = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_pending_order = None
        self.strategy_b_pending_order = None
        self.order_owners = {}

    def OnData(self, data):
        bars = data.Bars

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_crosses_above = False
        spy_crosses_below = False

        if bars.ContainsKey(spy):
            spy_close = bars[spy].Close
            prior_close = self.spy_previous_close
            prior_sma = self.spy_current_sma

            self.spy_closes.append(spy_close)

            if len(self.spy_closes) == 100:
                current_sma = sum(self.spy_closes) / Decimal(100)
            else:
                current_sma = None

            self.spy_previous_close = prior_close
            self.spy_previous_sma = prior_sma
            self.spy_current_sma = current_sma

            if (
                prior_close is not None
                and prior_sma is not None
                and current_sma is not None
            ):
                spy_crosses_above = (
                    prior_close <= prior_sma
                    and spy_close > current_sma
                )
                spy_crosses_below = (
                    prior_close >= prior_sma
                    and spy_close < current_sma
                )

            self.spy_previous_close = spy_close

        if bars.ContainsKey(aapl):
            aapl_close = bars[aapl].Close

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(self.Time, aapl_close)

        required = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        if any(not bars.ContainsKey(self.symbols[t]) for t in required):
            return

        if (
            self.spy_previous_sma is None
            or self.spy_current_sma is None
            or not self.aapl_rsi.IsReady
        ):
            return

        # Strategy A: evaluate sell before buy.
        if (
            self.strategy_a_lot > 0
            and self.strategy_a_pending_order is None
            and spy_crosses_below
        ):
            self.SubmitStrategyOrder(
                "A", spy, -self.strategy_a_lot, "Strategy A liquidation"
            )
        elif (
            self.strategy_a_lot == 0
            and self.strategy_a_pending_order is None
            and spy_crosses_above
        ):
            spy_close = bars[spy].Close
            target_value = Decimal("0.40") * self.Portfolio.TotalPortfolioValue
            quantity = int(math.floor(float(target_value / spy_close)))

            if quantity > 0:
                self.SubmitStrategyOrder(
                    "A", spy, quantity, "Strategy A 40% purchase"
                )

        # Strategy B: evaluate sell before buy.
        if (
            self.strategy_b_lot > 0
            and self.strategy_b_pending_order is None
            and self.aapl_rsi.Current.Value > Decimal(60)
        ):
            self.SubmitStrategyOrder(
                "B", aapl, -self.strategy_b_lot, "Strategy B liquidation"
            )
        elif (
            self.strategy_b_lot == 0
            and self.strategy_b_pending_order is None
            and self.aapl_red_streak >= 3
        ):
            cash_required = Decimal(20000)
            available_cash = self.Portfolio.CashBook["USD"].Amount

            if available_cash >= cash_required:
                aapl_close = bars[aapl].Close
                quantity = int(
                    math.floor(float(cash_required / aapl_close))
                )

                if quantity > 0:
                    self.SubmitStrategyOrder(
                        "B", aapl, quantity, "Strategy B $20,000 purchase"
                    )

    def SubmitStrategyOrder(self, owner, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, False, tag)
        order_id = ticket.OrderId
        self.order_owners[order_id] = owner

        if owner == "A":
            self.strategy_a_pending_order = order_id
        else:
            self.strategy_b_pending_order = order_id

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.order_owners:
            return

        owner = self.order_owners[order_id]

        if order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
            filled = int(order_event.FillQuantity)

            if owner == "A":
                self.strategy_a_lot = max(0, self.strategy_a_lot + filled)
            else:
                self.strategy_b_lot = max(0, self.strategy_b_lot + filled)

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            if owner == "A":
                self.strategy_a_pending_order = None
            else:
                self.strategy_b_pending_order = None

            del self.order_owners[order_id]

