    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.spy_current_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

    def OnData(self, data):
        self._update_market_state(data)

        if not all(data.Bars.ContainsKey(symbol)
                   for symbol in self.symbols.values()):
            return

        spy_lot = int(self.Portfolio[self.spy].Quantity)
        aapl_lot = int(self.Portfolio[self.aapl].Quantity)

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        spy_ready = (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_current_sma is not None
        )
        aapl_ready = (
            self.aapl_previous_close is not None
            and self.aapl_rsi.IsReady
        )

        if spy_lot > 0:
            if (
                spy_ready
                and self.spy_previous_close >= self.spy_previous_sma
                and spy_bar.Close < self.spy_current_sma
                and not self.Transactions.GetOpenOrders(self.spy)
            ):
                self.MarketOrder(self.spy, -spy_lot)
        else:
            if (
                spy_ready
                and self.spy_previous_close <= self.spy_previous_sma
                and spy_bar.Close > self.spy_current_sma
                and not self.Transactions.GetOpenOrders(self.spy)
            ):
                target_value = (
                    self.Portfolio.TotalPortfolioValue * Decimal("0.40")
                )
                quantity = int(target_value / spy_bar.Close)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)

        if aapl_lot > 0:
            if (
                aapl_ready
                and self.aapl_rsi.Current.Value > Decimal("60")
                and not self.Transactions.GetOpenOrders(self.aapl)
            ):
                self.MarketOrder(self.aapl, -aapl_lot)
        else:
            if (
                aapl_ready
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= Decimal("20000")
                and not self.Transactions.GetOpenOrders(self.aapl)
            ):
                quantity = int(Decimal("20000") / aapl_bar.Close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)

    def _update_market_state(self, data):
        if data.Bars.ContainsKey(self.spy):
            bar = data.Bars[self.spy]
            close = bar.Close

            old_sma = self.spy_current_sma
            old_close = self.spy_previous_close

            self.spy_closes.append(close)
            if len(self.spy_closes) == 100:
                self.spy_current_sma = (
                    sum(self.spy_closes, Decimal("0")) / Decimal("100")
                )
            else:
                self.spy_current_sma = None

            self.spy_previous_close = close
            self.spy_previous_sma = old_sma

            if old_close is None:
                self.spy_previous_sma = None

        if data.Bars.ContainsKey(self.aapl):
            bar = data.Bars[self.aapl]
            close = bar.Close

            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = close
            self.aapl_rsi.Update(bar.EndTime, close)

